  }

  /* Menu responsive */
  .menu-container {
    padding: var(--space-sm);
  }

  .filters-bar {
    flex-direction: column;
    align-items: stretch;
    gap: var(--space-sm);
    padding: var(--space-sm);
  }

  .filter-group {
    width: 100%;
  }

  .filter-buttons {
    width: 100%;
  }

  .filter-btn {
    flex: 1;
    text-align: center;
    padding: var(--space-sm);
  }

  .filter-toggle {
