  .exercises-grid {
    grid-template-columns: 1fr;
    gap: var(--space-sm);
  }

  .exercise-card {
    padding: var(--space-sm);
  }

  /* Piano responsive */
  .piano-overlay {
    padding-bottom: var(--space-sm);
    align-items: center;
  }

  .piano-popup {
    max-width: 100vw;
    width: 100%;
