    flex-shrink: 0;
  }

  .piano-key-black {
    width: 22px;
    height: 70px;
  }

  .piano-key-label {
    font-size: 8px;
  }

  /* Synth panel responsive */
  .synth-popup {
    width: 95vw;
    max-height: 90vh;
    border-radius: var(--radius-md);
  }

  .synth-header {
    padding: var(--space-sm);
  }

  .synth-title {
    font-size: var(--font-size-md);
  }

  .synth-content {
    padding: var(--space-sm);
  }

  .synth-presets {
    grid-template-columns: repeat(2, 1fr);
  }

  .synth-oscillators {
    grid-template-columns: repeat(2, 1fr);
  }

  .synth-slider-row {
    grid-template-columns: 55px 1fr 50px;
    gap: var(--space-xs);
  }

  .synth-slider-row label {
    font-size: var(--font-size-xs);
  }

  /* Memo popup responsive */
  .memo-popup {
    max-width: 95vw;
    max-height: 90vh;
  }

  .memo-content {
    padding: var(--space-sm);
  }

  .memo-notes-grid {
    grid-template-columns: repeat(4, 1fr);
    gap: var(--space-xs);
  }

  .memo-rhythm-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--space-sm);
  }

  .memo-intervals {
    grid-template-columns: repeat(2, 1fr);
  }

  /* Rhythm exercise responsive */
  .rhythm-track {
    padding: var(--space-sm);
    overflow-x: auto;
  }

  .rhythm-beat {
    width: 50px;
    height: 65px;
  }

  .rhythm-beat-symbol {
    font-size: 1.5rem;
  }

  .rhythm-tap-zone {
    width: 150px;
    height: 150px;
    font-size: var(--font-size-lg);
  }
}

/* Tablettes */
@media (min-width: 481px) and (max-width: 768px) {
  .exercises-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .piano-keyboard {
    height: 140px;
  }

  .piano-key-white {
    width: 36px;
    height: 125px;
  }

  .piano-key-black {
    width: 25px;
    height: 80px;
  }

  .synth-presets {
    grid-template-columns: repeat(3, 1fr);
  }

  .memo-notes-grid {
    grid-template-columns: repeat(7, 1fr);
  }

  .memo-rhythm-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* Desktop large */
@media (min-width: 1200px) {
  .exercises-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* Grands écrans */
@media (min-width: 1024px) {
  .piano-key-white {
    width: 44px;
    height: 150px;
  }

  .piano-key-black {
    width: 30px;
    height: 95px;
  }

  .synth-popup {
    max-width: 500px;
  }
}

