}
.btn-primary:hover { opacity: 0.9; }
.btn-secondary {
  width: 100%; padding: 14px; background: transparent;
  color: var(--color-text); border: 2px solid var(--color-border); border-radius: 12px; font-size: 1.1em;
  font-weight: 600; cursor: pointer; transition: background 0.2s, color 0.2s;
  margin-top: 10px;
}
.btn-secondary:hover { background: var(--color-bg-secondary); }
.btn-draw { background: #3b82f6; color: white; }
.btn-pass { background: #6b7280; color: white; }
.btn-quit { background: #dc2626; color: white; margin-top: 8px; }
.btn-rules { background: #8b5cf6; color: white; margin-top: 8px; text-decoration: none; text-align: center; display: block; }
.btn-draw:not(:disabled):hover, .btn-pass:not(:disabled):hover, .btn-quit:hover, .btn-rules:hover { opacity: 0.85; }

/* — Partie — */
#game-screen { width: 100%; max-width: 960px; }

/* Barre de statut */
.status-bar {
  background: var(--color-bg-secondary);
  border-radius: 14px;
  padding: 10px 16px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
  margin-bottom: 12px;
  color: var(--color-text);
}
.status-item { text-align: center; }
.status-label { font-size: 0.75em; opacity: 0.8; }
.status-value { font-size: 1.1em; font-weight: 700; }

/* Scores */
#scores-bar {
  display: flex; gap: 10px; flex-wrap: wrap;
  justify-content: center; margin-bottom: 12px;
}
.score-card {
  background: var(--color-bg-secondary); border-radius: 12px;
  padding: 8px 16px; color: var(--color-text); text-align: center;
  border: 2px solid transparent; transition: border-color 0.2s;
}
.score-card.active { border-color: var(--color-accent); background: var(--color-bg-card); }
.score-card .player-name { font-size: 0.8em; opacity: 0.9; }
.score-card .player-score { font-size: 1.4em; font-weight: 700; }

/* Zone de jeu principale */
#main-area {
  display: flex; gap: 12px; align-items: flex-start;
  flex-wrap: wrap; justify-content: center;
}

/* Plateau SVG */
#board-container {
  background: var(--color-bg-card); border-radius: 16px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.2);
  overflow: hidden; position: relative;
  flex: 1; min-width: min(320px, 100%);
}
#board-svg { display: block; width: 100%; height: 480px; cursor: default; }

/* Panneau latéral */
#side-panel {
  background: var(--color-bg-card); border-radius: 16px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.2);
  padding: 16px; min-width: 200px; max-width: 260px; width: 100%;
}
#side-panel h3 { font-size: 0.9em; color: var(--color-text-muted); margin-bottom: 10px; text-transform: uppercase; letter-spacing: 0.05em; }
.rack-button { background: transparent; border: 2px solid var(--color-border); border-radius: var(--radius-md); padding: 2px; cursor: pointer; }
.rack-button[aria-pressed="true"] { border-color: var(--color-accent); background: var(--color-bg-secondary); }
#placement-controls { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; }
#placement-controls select, #placement-controls button {
  width: 100%; padding: 10px; border-radius: var(--radius-md);
  border: 1px solid var(--color-border); background: var(--color-bg-secondary); color: var(--color-text);
}
#placement-controls button:not(:disabled) { cursor: pointer; }
#placement-controls :disabled { opacity: 0.6; }
#hint, #end-subtitle { color: var(--color-text-muted); }

/* Réglette */
#rack-container { margin-bottom: 16px; }
#rack { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; }
.rack-tile {
  cursor: pointer; transition: transform 0.15s, filter 0.15s;
}
.rack-tile:hover { transform: scale(1.08); }
.rack-tile.selected { filter: drop-shadow(0 0 6px #f97316); }
.rack-tile.drawn { filter: drop-shadow(0 0 6px #3b82f6); }

/* Boutons d'action */
#actions { display: flex; flex-direction: column; gap: 8px; }
.btn-action {
  padding: 10px 14px; border: none; border-radius: 10px;
  font-size: 0.95em; font-weight: 600; cursor: pointer; transition: opacity 0.2s;
}
.btn-action:disabled { opacity: 0.4; cursor: not-allowed; }
.btn-draw { background: #3b82f6; color: white; }
.btn-pass { background: #6b7280; color: white; }
.btn-quit { background: #dc2626; color: white; margin-top: 8px; }
.btn-rules { background: #8b5cf6; color: white; margin-top: 8px; text-decoration: none; text-align: center; display: block; }
.btn-draw:not(:disabled):hover, .btn-pass:not(:disabled):hover, .btn-quit:hover, .btn-rules:hover { opacity: 0.85; }

/* Notification de bonus */
#bonus-notif {
  position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%) scale(0);
  background: var(--color-bg-card); border-radius: 20px; padding: 24px 36px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.4); text-align: center;
  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  z-index: 100; pointer-events: none;
}
#bonus-notif.show { transform: translate(-50%, -50%) scale(1); }
#bonus-notif .bonus-emoji { font-size: 3em; }
#bonus-notif .bonus-text { font-size: 1.3em; font-weight: 700; color: var(--color-text); margin-top: 8px; }
#bonus-notif .bonus-pts { font-size: 2em; font-weight: 900; color: #f97316; }

/* Écran de fin */
#end-screen {
  background: var(--color-bg-card); border-radius: 20px; padding: 36px;
  max-width: 440px; width: 100%;
  box-shadow: 0 20px 60px rgba(0,0,0,0.3); text-align: center;
}
#end-screen h2 { font-size: 2em; margin-bottom: 8px; color: var(--color-text); }
.podium { list-style: none; margin: 20px 0; }
.podium li {
  display: flex; justify-content: space-between; align-items: center;
  padding: 12px 16px; margin-bottom: 8px; border-radius: 12px;
  font-weight: 600;
}
.podium li:nth-child(1) { background: #fef3c7; color: #92400e; font-size: 1.1em; }
.podium li:nth-child(2) { background: #f1f5f9; color: #475569; }
.podium li:nth-child(3) { background: #fef9f0; color: #92400e; }
.podium li:nth-child(n+4) { background: #f8fafc; color: #64748b; }
.podium .rank { font-size: 1.4em; }

/* Modale de confirmation */
#confirm-overlay {
  display: none; position: fixed; inset: 0;
  background: rgba(0,0,0,0.5); z-index: 200;
  justify-content: center; align-items: center;
}
#confirm-overlay.show { display: flex; }
#confirm-dialog {
  background: var(--color-bg-card); border-radius: 20px; padding: 32px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.4); text-align: center;
  max-width: 340px; width: 90%;
}
#confirm-dialog p { color: var(--color-text); font-size: 1.1em; font-weight: 600; margin-bottom: 20px; }
#confirm-dialog .confirm-buttons { display: flex; gap: 10px; justify-content: center; }
#confirm-dialog .btn-confirm-yes {
  padding: 10px 24px; background: #dc2626; color: white; border: none;
  border-radius: 10px; font-size: 0.95em; font-weight: 600; cursor: pointer;
}
#confirm-dialog .btn-confirm-no {
  padding: 10px 24px; background: #6b7280; color: white; border: none;
  border-radius: 10px; font-size: 0.95em; font-weight: 600; cursor: pointer;
}
#confirm-dialog .btn-confirm-yes:hover, #confirm-dialog .btn-confirm-no:hover { opacity: 0.85; }
.btn-action, #confirm-dialog .btn-confirm-yes, #confirm-dialog .btn-confirm-no {
  background: var(--color-accent); color: var(--color-text-inverse);
}
@media (max-width: 480px) {
  #setup-screen, #end-screen { padding: 20px; }
  #board-svg { height: 320px; }
  #side-panel { max-width: none; min-width: 0; }
}

/tools/relativity-lab/index.html:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: var(--font-family);
  background: var(--color-bg);
  color: var(--color-text);
}

.app-container {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  position: relative;
}

#canvas-container {
  flex: 1;
  position: relative;
  overflow: hidden;
}

.panels {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.panels > div {
  pointer-events: auto;
  max-height: calc(100dvh - 2 * var(--space-md));
  overflow: auto;
  overscroll-behavior: contain;
}

.panels > .lil-gui.root {
  position: absolute;
  top: var(--space-md);
  right: 310px;
}

.simulation-actions { display: contents; }

#canvas-container canvas {
  display: block;
  touch-action: none; /* Empêche les gestes natifs qui bloquent le zoom */
}

/* === Styles communs aux panneaux déplaçables === */
.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: calc(-1 * var(--space-md));
  margin-bottom: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  background: var(--color-bg);
  border-radius: var(--radius-md) var(--radius-md) 0 0;
  border-bottom: 1px solid var(--color-border);
  user-select: none;
}

.panel-title {
  font-weight: bold;
  font-size: var(--font-size-sm);
}

.panel-close {
  background: none;
  border: none;
  color: var(--color-text-muted);
  font-size: var(--font-size-lg);
  cursor: pointer;
  padding: 0 4px;
  line-height: 1;
}

.panel-close:hover {
  color: var(--color-accent);
}

/* Curseur grab pour tous les headers déplaçables */
[data-drag-handle] {
  cursor: grab;
}

[data-drag-handle]:active {
  cursor: grabbing;
}

/* HUD Styles - Vue "Je suis..." */
.hud {
  position: absolute;
  top: var(--space-md);
  left: var(--space-md);
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  min-width: 200px;
  max-width: 260px;
  font-family: var(--font-family);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  z-index: 100;
  box-shadow: 0 4px 12px var(--color-shadow);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: auto;
}

.hud-state {
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
  font-size: var(--font-size-xs);
}

.hud-state--running {
  background: var(--color-success);
  color: var(--color-text-inverse);
}

.hud-section {
  margin-bottom: var(--space-sm);
}

.hud-label {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.hud-divider {
  height: 1px;
  background: var(--color-border);
  margin: var(--space-sm) 0;
}

.hud-select {
  width: 100%;
  padding: 8px 12px;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  font-family: var(--font-family);
  font-size: var(--font-size-md);
  font-weight: bold;
  cursor: pointer;
}

.hud-select:hover {
  border-color: var(--color-accent);
}

.hud-select:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
  border-color: var(--color-accent);
}

.hud-my-name {
  font-size: var(--font-size-xl);
  font-weight: bold;
  color: var(--color-accent);
}

.hud-my-tau {
  font-family: var(--font-mono);
  font-size: var(--font-size-xl);
  font-weight: bold;
}

.hud-my-emissions {
  display: flex;
  gap: var(--space-md);
}

.hud-emission {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
}

.hud-emission--h {
  background: rgba(255, 107, 107, 0.15);
  border: 1px solid rgba(255, 107, 107, 0.3);
}

.hud-emission--v {
  background: rgba(74, 222, 128, 0.15);
  border: 1px solid rgba(74, 222, 128, 0.3);
}

.hud-emission-label {
  font-weight: bold;
  font-size: var(--font-size-md);
}

.hud-emission--h .hud-emission-label {
  color: #ff6b6b;
}

.hud-emission--v .hud-emission-label {
  color: #4ade80;
}

.hud-emission-value {
  font-size: var(--font-size-lg);
  font-weight: 600;
}

.hud-my-cmb, .hud-my-mass {
  font-family: var(--font-mono);
  font-size: var(--font-size-md);
  font-weight: 600;
}

/* Ce que j'ai reçu - version compacte */
.hud-received-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.hud-no-received {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  font-style: italic;
}

.hud-received-item {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  padding: 4px 8px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  font-size: var(--font-size-xs);
}

.hud-received-name {
  font-weight: 600;
  min-width: 50px;
}

.hud-received-ticks {
  display: flex;
  gap: 4px;
  font-family: var(--font-mono);
}

.hud-tick {
  padding: 1px 4px;
  border-radius: 2px;
}

.hud-tick--h {
  color: #ff6b6b;
  background: rgba(255, 107, 107, 0.15);
}

.hud-tick--v {
  color: #4ade80;
  background: rgba(74, 222, 128, 0.15);
}

.hud-received-distance {
  font-family: var(--font-mono);
  color: var(--color-text-muted);
  margin-left: auto;
}

.hud-inferred-gamma {
  color: var(--color-warning);
  background: rgba(251, 191, 36, 0.15);
  padding: 1px 4px;
  border-radius: 2px;
  font-family: var(--font-mono);
}

.hud-row {
  display: flex;
  gap: var(--space-md);
}

.hud-row > div {
  flex: 1;
}

.hud-help {
  margin-top: var(--space-sm);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
}

/* === Vue cockpit (ObserverView) === */
.observer-view {
  position: absolute;
  top: var(--space-md);
  right: var(--space-md);
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  min-width: 220px;
  max-width: 280px;
  font-family: var(--font-family);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  z-index: 100;
  box-shadow: 0 4px 12px var(--color-shadow);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: auto;
}

.observer-view-header {
  display: flex;
  align-items: baseline;
  gap: var(--space-xs);
  margin-bottom: var(--space-sm);
}

.observer-view-title {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.observer-view-name {
  font-size: var(--font-size-lg);
  font-weight: bold;
  color: var(--color-accent);
}

.observer-view-section {
  margin-bottom: var(--space-sm);
}

.observer-view-label {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.observer-view-tau {
  font-family: var(--font-mono);
  font-size: var(--font-size-xl);
  font-weight: bold;
}

.observer-view-clocks {
  display: flex;
  gap: var(--space-md);
}

.observer-view-divider {
  height: 1px;
  background: var(--color-border);
  margin: var(--space-sm) 0;
}

.observer-view-received {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.ov-clock {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
}

.ov-clock--h {
  background: rgba(255, 107, 107, 0.15);
  border: 1px solid rgba(255, 107, 107, 0.3);
}

.ov-clock--v {
  background: rgba(74, 222, 128, 0.15);
  border: 1px solid rgba(74, 222, 128, 0.3);
}

.ov-clock-icon {
  font-weight: bold;
  font-size: var(--font-size-sm);
}

.ov-clock--h .ov-clock-icon {
  color: #ff6b6b;
}

.ov-clock--v .ov-clock-icon {
  color: #4ade80;
}

.ov-clock-value {
  font-size: var(--font-size-lg);
  font-weight: 600;
}

.ov-clock--small {
  padding: 3px 8px;
}

.ov-clock--small .ov-clock-icon {
  font-size: var(--font-size-xs);
}

.ov-clock--small .ov-clock-value {
  font-size: var(--font-size-sm);
}

.ov-received-observer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-xs) var(--space-sm);
  background: var(--color-bg);
  border-radius: var(--radius-sm);
}

.ov-received-observer--empty {
  opacity: 0.5;
}

.ov-received-name {
  font-weight: 600;
  font-size: var(--font-size-sm);
}

.ov-received-clocks {
  display: flex;
  gap: var(--space-xs);
}

.ov-no-data {
  font-style: italic;
  color: var(--color-text-muted);
  font-size: var(--font-size-xs);
}

/* === Gros bouton Play/Stop === */
.play-button {
  position: absolute;
  bottom: var(--space-lg);
  left: 50%;
  transform: translateX(-50%);
  z-index: 200;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-md) var(--space-xl);
  background: var(--color-accent);
  color: var(--color-text-inverse);
  border: none;
  border-radius: var(--radius-lg);
  font-family: var(--font-family);
  font-size: var(--font-size-lg);
  font-weight: bold;
  cursor: pointer;
  transition: all var(--transition-normal);
  box-shadow: 0 4px 20px rgba(233, 69, 96, 0.4);
}

.play-button:hover {
  transform: translateX(-50%) scale(1.05);
  box-shadow: 0 6px 24px rgba(233, 69, 96, 0.5);
}

.play-button:active {
  transform: translateX(-50%) scale(0.98);
}

.play-button--running {
  background: var(--color-warning);
  box-shadow: 0 4px 20px rgba(251, 191, 36, 0.4);
}

.play-button--running:hover {
  box-shadow: 0 6px 24px rgba(251, 191, 36, 0.5);
}

.play-button-icon {
  font-size: 1.5em;
}

/* Bouton Reset à côté */
.reset-button {
  position: absolute;
  bottom: var(--space-lg);
  left: calc(50% + 100px);
  z-index: 200;
  padding: var(--space-sm) var(--space-md);
  background: var(--color-bg-secondary);
  color: var(--color-text);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  font-family: var(--font-family);
  font-size: var(--font-size-md);
  cursor: pointer;
  transition: all var(--transition-normal);
}

.reset-button:hover {
  background: var(--color-bg-hover);
  border-color: var(--color-accent);
}

/* lil-gui customisation pour s'intégrer au thème */
.lil-gui {
  --background-color: var(--color-bg-secondary);
  --text-color: var(--color-text);
  --title-background-color: var(--color-bg);
  --title-text-color: var(--color-text);
  --widget-color: var(--color-bg);
  --hover-color: var(--color-bg-hover);
  --focus-color: var(--color-accent);
  --number-color: var(--color-accent);
  --string-color: var(--color-success);
  font-family: var(--font-family) !important;
}

.lil-gui .title {
  font-weight: 600;
}

/* Loading state */
.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
}

.loading::after {
  content: '';
  width: 24px;
  height: 24px;
  margin-left: var(--space-sm);
  border: 3px solid var(--color-border);
  border-top-color: var(--color-accent);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* === Panneau Moteur === */
.motor-panel {
  position: absolute;
  bottom: calc(var(--space-lg) + 60px);
  right: var(--space-md);
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  width: 280px;
  font-family: var(--font-family);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  z-index: 100;
  box-shadow: 0 4px 12px var(--color-shadow);
  backdrop-filter: blur(8px);
  pointer-events: auto;
}

.motor-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-sm);
}

.motor-panel-title {
  font-weight: bold;
  font-size: var(--font-size-md);
}

.motor-panel-status {
  font-size: var(--font-size-xs);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  background: var(--color-bg);
}

.motor-panel-status--burning {
  background: var(--color-warning);
  color: var(--color-text-inverse);
  animation: pulse 0.5s infinite;
}

.motor-panel-status--success {
  background: var(--color-success);
  color: var(--color-text-inverse);
}

.motor-panel-status--error {
  background: var(--color-error);
  color: var(--color-text-inverse);
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.motor-panel-section {
  margin-bottom: var(--space-sm);
}

.motor-panel-section--small {
  margin-bottom: var(--space-xs);
}

.motor-panel-label {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}

.motor-panel-mass {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--space-xs);
}

.motor-mass-value {
  font-family: var(--font-mono);
  font-size: var(--font-size-lg);
  font-weight: bold;
}

.motor-mass-unit {
  color: var(--color-text-muted);
}

.motor-mass-bar {
  width: 100%;
  height: 6px;
  background: var(--color-bg);
  border-radius: 3px;
  overflow: hidden;
  margin-top: 4px;
}

.motor-mass-fill {
  height: 100%;
  background: var(--color-success);
  transition: width 0.2s, background 0.2s;
}

.motor-direction-controls {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.motor-direction-row {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.motor-direction-row label {
  width: 20px;
  font-family: var(--font-mono);
  font-weight: bold;
}

.motor-direction-row input[type="range"] {
  flex: 1;
  height: 4px;
}

.motor-direction-row span {
  width: 30px;
  text-align: right;
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
}

.motor-direction-presets {
  display: flex;
  gap: var(--space-xs);
  margin-top: var(--space-xs);
}

.motor-preset {
  flex: 1;
  padding: 4px;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: var(--font-size-md);
}

.motor-preset:hover {
  background: var(--color-bg-hover);
  border-color: var(--color-accent);
}

.motor-impulse-controls {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.motor-impulse-controls input[type="range"] {
  flex: 1;
}

.motor-impulse-controls span {
  font-family: var(--font-mono);
  min-width: 50px;
}

.motor-impulse-info {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  margin-top: 2px;
}

.motor-impulse-info span:last-child {
  font-family: var(--font-mono);
  color: var(--color-accent);
}

.motor-thrust-controls {
  display: flex;
  gap: var(--space-xs);
}

.motor-thrust-btn {
  flex: 1;
  padding: var(--space-xs) var(--space-sm);
  border: none;
  border-radius: var(--radius-sm);
  font-family: var(--font-family);
  font-size: var(--font-size-xs);
  font-weight: bold;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.motor-thrust-btn--forward {
  background: var(--color-success);
  color: var(--color-text-inverse);
}

.motor-thrust-btn--backward {
  background: var(--color-warning);
  color: var(--color-text-inverse);
}

.motor-thrust-btn--fire {
  background: var(--color-accent);
  color: var(--color-text-inverse);
}

.motor-thrust-btn:hover {
  transform: scale(1.02);
  filter: brightness(1.1);
}

.motor-thrust-btn:active {
  transform: scale(0.98);
}

.motor-history {
  max-height: 80px;
  overflow-y: auto;
  font-size: var(--font-size-xs);
}

.motor-history-empty {
  color: var(--color-text-muted);
  font-style: italic;
}

.motor-history-item {
  display: flex;
  justify-content: space-between;
  padding: 2px 0;
  border-bottom: 1px solid var(--color-border);
  font-family: var(--font-mono);
}

.motor-history-tau {
  color: var(--color-text-muted);
}

.motor-history-dv {
  color: var(--color-success);
}

.motor-history-mass {
  color: var(--color-warning);
}

/* Ajustement HUD pour nouvelle info */
.hud-observer-meta {
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  margin-top: 2px;
}

.hud-meta-item {
  font-family: var(--font-mono);
}

/* === Graphique Doppler === */
.doppler-graph {
  position: absolute;
  bottom: calc(var(--space-lg) + 60px);
  left: var(--space-md);
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-sm);
  width: 320px;
  height: 180px;
  font-family: var(--font-family);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  z-index: 100;
  box-shadow: 0 4px 12px var(--color-shadow);
  backdrop-filter: blur(8px);
  display: flex;
  flex-direction: column;
  pointer-events: auto;
}

.doppler-graph-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-xs);
  flex-shrink: 0;
}

.doppler-graph-title {
  font-weight: bold;
  font-size: var(--font-size-sm);
}

.doppler-graph-timewindow {
  padding: 2px 6px;
  font-size: var(--font-size-xs);
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  cursor: pointer;
}

.doppler-graph-timewindow:hover {
  border-color: var(--color-accent);
}

.doppler-graph-legend {
  display: flex;
  gap: var(--space-xs);
  font-size: var(--font-size-xs);
  margin-bottom: var(--space-xs);
}

.doppler-legend-item {
  padding: 1px 4px;
  border-radius: 2px;
}

.doppler-legend--red {
  background: rgba(255, 107, 107, 0.3);
  color: #ff6b6b;
}

.doppler-legend--green {
  background: rgba(74, 222, 128, 0.3);
  color: #4ade80;
}

.doppler-legend--blue {
  background: rgba(74, 179, 247, 0.3);
  color: #4ab3f7;
}

.doppler-graph-canvas-wrapper {
  flex: 1;
  min-height: 0;
  position: relative;
}

.doppler-graph-canvas {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: var(--radius-sm);
}

/* === Panneau Oscilloscope === */
.clock-panel {
  position: absolute;
  top: var(--space-md);
  left: 280px;
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: var(--space-sm);
  width: 380px;
  height: 260px;
  font-family: var(--font-family);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  z-index: 100;
  box-shadow: 0 4px 12px var(--color-shadow);
  backdrop-filter: blur(8px);
  pointer-events: auto;
  display: flex;
  flex-direction: column;
}

.clock-panel .panel-header {
  margin: calc(-1 * var(--space-sm));
  margin-bottom: var(--space-xs);
  padding: var(--space-xs) var(--space-sm);
  flex-shrink: 0;
}

.oscillo-controls {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.oscillo-select {
  padding: 2px 6px;
  font-size: var(--font-size-xs);
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  cursor: pointer;
}

.oscillo-select:hover {
  border-color: var(--color-accent);
}

.oscillo-hint {
  font-size: 10px;
  color: var(--color-text-muted);
  margin-bottom: 4px;
  flex-shrink: 0;
}

.oscillo-canvas-wrapper {
  flex: 1 1 auto;
  min-height: 100px;
  position: relative;
  border-radius: var(--radius-sm);
  overflow: hidden;
  background: rgba(0, 0, 0, 0.3);
}

.oscillo-canvas-wrapper canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
}

.oscillo-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
  font-size: 10px;
  flex-shrink: 0;
}

.oscillo-legend-item {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  background: var(--color-bg);
  border-radius: var(--radius-sm);
  border-left: 2px solid;
}

.oscillo-legend-color {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

/* Les panneaux quittent le canvas quand la fenêtre ne permet plus les superpositions. */
@media (max-width: 1100px), (max-height: 650px) {
  html, body { height: auto; min-height: 100%; overflow: auto; }
  .app-container { height: auto; min-height: 100dvh; }
  #canvas-container { flex: none; height: clamp(240px, 50dvh, 420px); }
  .panels {
    position: static;
    display: flex;
    flex: none;
    flex-direction: column;
    gap: var(--space-md);
    padding: var(--space-md);
    min-height: 0;
  }
  .panels > div, .panels > .lil-gui.root {
    position: static !important;
    inset: auto !important;
    flex: none;
    width: 100% !important;
    height: auto;
    min-width: 0;
    min-height: 0;
    max-width: none;
    max-height: none;
    overflow: visible;
  }
  /* Seuls les graphiques ont une hauteur fixe ; les commandes restent dans le flux. */
  .panels .oscillo-canvas-wrapper {
    flex: none;
    height: 180px;
  }
  .panels .doppler-graph-canvas-wrapper {
    flex: none;
    height: 120px;
  }
  .panels > .lil-gui.root > .children {
    max-height: none;
    overflow: visible;
  }
  [data-drag-handle] { cursor: default !important; }
  /* Le statut ne doit pas deplacer un bouton pendant une poussee maintenue. */
  .motor-panel-header {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-xs);
  }
  .motor-thrust-btn { min-height: 44px; }
  .simulation-actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--space-sm);
    padding: var(--space-sm);
    flex: none;
    background: var(--color-bg-secondary);
    border-top: 1px solid var(--color-border);
  }
  .play-button, .reset-button {
    position: static;
    transform: none;
    padding: var(--space-sm) var(--space-md);
  }
  .play-button:hover, .play-button:active { transform: none; }
}

/tools/json-formatter.html:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  transition: background-color var(--transition-normal), color var(--transition-normal);
}

header {
  padding: var(--space-md);
  background: var(--color-bg-secondary);
  border-bottom: 1px solid var(--color-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background-color var(--transition-normal), border-color var(--transition-normal);
}

header h1 {
  font-size: var(--font-size-lg);
  font-weight: 600;
}

header h1 span {
  color: var(--color-accent);
}

.actions {
  display: flex;
  gap: var(--space-sm);
}

button {
  padding: var(--space-sm) var(--space-md);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: var(--font-size-sm);
  font-weight: 500;
  transition: all var(--transition-normal);
}

button.primary {
  background: var(--color-accent);
  color: var(--color-text-inverse);
}

button.primary:hover {
  background: var(--color-accent-hover);
}

button.secondary {
  background: var(--color-bg);
  color: var(--color-text);
  border: 1px solid var(--color-border);
}

button.secondary:hover {
  background: var(--color-border);
}

main {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  min-height: 26rem;
  min-width: 0;
  background: var(--color-border);
}

@media (max-width: 768px) {
  main {
    grid-template-columns: 1fr;
    grid-template-rows: 1fr 1fr;
  }
}

.panel {
  min-width: 0;
  background: var(--color-bg);
  display: flex;
  flex-direction: column;
  transition: background-color var(--transition-normal);
}

.panel-header {
  padding: 0.75rem var(--space-md);
  background: var(--color-bg-secondary);
  border-bottom: 1px solid var(--color-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: background-color var(--transition-normal), border-color var(--transition-normal);
}

@media (max-width: 480px) {
  header, footer { flex-wrap: wrap; gap: var(--space-sm); }
  .actions { flex-wrap: wrap; }
  textarea { min-height: 14rem; }
}

.panel-header h2 {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--color-text-muted);
}

.status {
  font-size: var(--font-size-xs);
  padding: var(--space-xs) var(--space-sm);
  border-radius: 3px;
}

.status.valid {
  background: var(--color-success-light);
  color: var(--color-success);
}

.status.invalid {
  background: var(--color-error-light);
  color: var(--color-error);
}

textarea {
  flex: 1;
  padding: var(--space-md);
  background: var(--color-bg);
  border: none;
  color: var(--color-text);
  font-family: var(--font-mono);
  font-size: var(--font-size-sm);
  line-height: 1.5;
  resize: none;
  outline: none;
  transition: background-color var(--transition-normal), color var(--transition-normal);
}

textarea::placeholder {
  color: var(--color-text-muted);
}

textarea:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: -3px;
}

.output {
  flex: 1;
  padding: var(--space-md);
  overflow: auto;
  font-family: var(--font-mono);
  font-size: var(--font-size-sm);
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.output.error {
  color: var(--color-error);
}

/* Coloration syntaxique */
.string { color: var(--color-syntax-string); }
.number { color: var(--color-syntax-number); }
.boolean { color: var(--color-syntax-boolean); }
.null { color: var(--color-syntax-null); }
.key { color: var(--color-syntax-key); }

footer {
  padding: var(--space-sm) var(--space-md);
  background: var(--color-bg-secondary);
  border-top: 1px solid var(--color-border);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  display: flex;
  justify-content: space-between;
  transition: background-color var(--transition-normal), border-color var(--transition-normal);
}

.kbd {
  display: inline-block;
  padding: 0.1rem 0.4rem;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 3px;
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
  transition: background-color var(--transition-normal), border-color var(--transition-normal);
}
